fn main() -> Result<(), Box<dyn std::error::Error>> {
    emit_engine_versions()?;
    link_cli_with_lld()?;
    let attributes = tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(COMMANDS));
    tauri_build::try_build(with_windows_manifest(attributes)?)?;
    Ok(())
}

/// This package's folder, as Cargo says when it runs the script. Read at run time, not with
/// `env!`: the script's binary is reused by every checkout that shares a target folder, so a
/// compile-time path pointed at whichever checkout built it first (a worktree since deleted, its
/// Cargo.lock gone, and every build failing).
fn manifest_dir() -> Result<std::path::PathBuf, Box<dyn std::error::Error>> {
    Ok(std::env::var_os("CARGO_MANIFEST_DIR").ok_or("cargo didn't set CARGO_MANIFEST_DIR")?.into())
}

/// Records the Isoloom and Isothrum versions this launcher bundles, read from the pinned entries
/// in Cargo.lock, as compile-time env vars the `version` module exposes. The catalogue query uses
/// them so only labs this launcher can generate (Isoloom) and run (Isothrum) are shown.
fn emit_engine_versions() -> Result<(), Box<dyn std::error::Error>> {
    let lock = manifest_dir()?.join("Cargo.lock");
    println!("cargo:rerun-if-changed={}", lock.display());
    let text = std::fs::read_to_string(&lock)?;
    let isoloom = locked_version(&text, "isoloom-spec").ok_or("isoloom-spec not found in Cargo.lock")?;
    // Every bundled isoloom-* crate must be the same version. The backends (isoloom-compose,
    // isoloom-plan, isoloom-render, ...) come in transitively at `^1.0`, so bumping the direct deps
    // alone leaves them a patch behind: a split-brain engine that advertises `isoloom-spec`'s
    // version but generates with an older backend (which once silently dropped the build+image pull
    // step, so the launcher built labs it should have pulled). Make that skew a hard build error.
    let skew: Vec<String> = isoloom_versions(&text).into_iter().filter(|(_, v)| *v != isoloom).map(|(n, v)| format!("{n} {v}")).collect();
    if !skew.is_empty() {
        return Err(format!("bundled Isoloom crates disagree with isoloom-spec {isoloom}: {}. Realign the lockfile (cargo update -p <crate>) so the whole engine is one version.", skew.join(", ")).into());
    }
    let isothrum = locked_version(&text, "isothrum-runner").ok_or("isothrum-runner not found in Cargo.lock")?;
    println!("cargo:rustc-env=CYBERCTF_ISOLOOM_VERSION={isoloom}");
    println!("cargo:rustc-env=CYBERCTF_ISOTHRUM_VERSION={isothrum}");
    Ok(())
}

/// The version of package `name` in a Cargo.lock: the `version = "..."` of the `[[package]]`
/// block whose `name = "..."` matches. Returns None when the package is absent.
fn locked_version(lock: &str, name: &str) -> Option<String> {
    let needle = format!("name = \"{name}\"");
    let mut after_name = false;
    for line in lock.lines() {
        let line = line.trim();
        if line == needle {
            after_name = true;
        } else if after_name {
            if let Some(rest) = line.strip_prefix("version = ") {
                return Some(rest.trim_matches('"').to_owned());
            }
            if line == "[[package]]" {
                after_name = false;
            }
        }
    }
    None
}

/// Every `isoloom-*` package in a Cargo.lock, as (name, version). Used to assert the bundled
/// engine is one coherent version (see `emit_engine_versions`): `version` directly follows `name`
/// in each `[[package]]` block.
fn isoloom_versions(lock: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut name: Option<String> = None;
    for line in lock.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("name = ") {
            let n = rest.trim_matches('"');
            name = n.starts_with("isoloom-").then(|| n.to_owned());
        } else if let (Some(n), Some(rest)) = (name.as_deref(), line.strip_prefix("version = ")) {
            out.push((n.to_owned(), rest.trim_matches('"').to_owned()));
            name = None;
        } else if line == "[[package]]" {
            name = None;
        }
    }
    out
}

/// On Linux, the command line (`cyberctf`) links with lld, the linker Rust ships
/// (`<sysroot>/lib/rustlib/<host>/bin/gcc-ld/ld.lld`), so it links no GTK nor web view
/// (`tests/cli.rs`'s `it_links_no_gui_library`).
///
/// It is built from the app's library, so every library Tauri's window and web view need is on its
/// link line, each `--as-needed`: kept only if the executable uses it. lld decides that after
/// dropping the code nothing reaches, so none is kept. GNU ld decides it on every archive member it
/// pulled in, reached or not, and a debug build's shared generics pull in Tauri's, tao's and wry's:
/// on `x86_64` Rust links with lld by default, on aarch64 with the system's (GNU ld), whose `cyberctf`
/// needed GTK, GDK, Pango, Cairo and `WebKitGTK`, and wouldn't start where they aren't installed.
fn link_cli_with_lld() -> Result<(), Box<dyn std::error::Error>> {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("linux") || std::env::var("CARGO_CFG_TARGET_ENV").as_deref() != Ok("gnu") {
        return Ok(());
    }
    let rustc = std::env::var_os("RUSTC").ok_or("cargo didn't set RUSTC")?;
    let host = std::env::var("HOST")?;
    #[expect(clippy::disallowed_methods, reason = "a build script, which has no platform::exec: it asks rustc for its sysroot")]
    let sysroot = std::process::Command::new(&rustc).args(["--print", "sysroot"]).output()?;
    if !sysroot.status.success() {
        return Err(format!("rustc --print sysroot failed ({})", sysroot.status).into());
    }
    let gcc_ld = std::path::Path::new(String::from_utf8(sysroot.stdout)?.trim()).join("lib").join("rustlib").join(host).join("bin").join("gcc-ld");
    if !gcc_ld.join("ld.lld").is_file() {
        // A Rust without its lld (a distribution's package): the default linker, and the test says
        // what it linked.
        println!("cargo:warning={} has no ld.lld: cyberctf links with the default linker, which may keep GTK", gcc_ld.display());
        return Ok(());
    }
    println!("cargo:rustc-link-arg-bin=cyberctf=-B{}", gcc_ld.display());
    println!("cargo:rustc-link-arg-bin=cyberctf=-fuse-ld=lld");
    Ok(())
}

/// On Windows, tauri-build embeds the app manifest (Common Controls v6) in the app binary only,
/// so the unit-test executable ran without it and failed to load (`STATUS_ENTRYPOINT_NOT_FOUND`:
/// comctl32's `TaskDialogIndirect` needs v6). Embed the same manifest in every linked target, by
/// the target's toolchain: the MSVC linker's own flags, or, on a GNU target (MinGW, llvm-mingw),
/// a resource object its `windres` compiles.
fn with_windows_manifest(attributes: tauri_build::Attributes) -> Result<tauri_build::Attributes, Box<dyn std::error::Error>> {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return Ok(attributes);
    }
    let manifest = manifest_dir()?.join("windows-app-manifest.xml");
    match std::env::var("CARGO_CFG_TARGET_ENV").as_deref() {
        Ok("msvc") => {
            println!("cargo:rustc-link-arg=/MANIFEST:EMBED");
            println!("cargo:rustc-link-arg=/MANIFESTINPUT:{}", manifest.display());
        }
        Ok("gnu") => println!("cargo:rustc-link-arg={}", gnu_manifest_object(&manifest)?.display()),
        _ => return Ok(attributes),
    }
    println!("cargo:rerun-if-changed={}", manifest.display());
    Ok(attributes.windows_attributes(tauri_build::WindowsAttributes::new_without_app_manifest()))
}

/// `manifest` as a COFF resource object (`RT_MANIFEST`, id 1) in the script's output folder,
/// compiled by the GNU toolchain's `windres`: `$WINDRES` when set, else `<arch>-w64-mingw32-windres`.
fn gnu_manifest_object(manifest: &std::path::Path) -> Result<std::path::PathBuf, Box<dyn std::error::Error>> {
    let out = std::path::PathBuf::from(std::env::var_os("OUT_DIR").ok_or("cargo didn't set OUT_DIR")?);
    let rc = out.join("app-manifest.rc");
    // windres reads `\` in a string as an escape: the path with forward slashes, which it takes.
    std::fs::write(&rc, format!("1 24 \"{}\"\n", manifest.display().to_string().replace('\\', "/")))?;
    let object = out.join("app-manifest.o");
    println!("cargo:rerun-if-env-changed=WINDRES");
    let windres = std::env::var("WINDRES").unwrap_or_else(|_| format!("{}-w64-mingw32-windres", std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default()));
    #[expect(clippy::disallowed_methods, reason = "a build script, which has no platform::exec: it runs the toolchain's resource compiler")]
    let status = std::process::Command::new(&windres).arg("--input").arg(&rc).arg("--output").arg(&object).arg("--output-format=coff").status();
    match status {
        Ok(s) if s.success() => Ok(object),
        Ok(s) => Err(format!("{windres} failed compiling the app manifest ({s})").into()),
        Err(e) => Err(format!("{windres} (the GNU toolchain's resource compiler; set WINDRES to another) couldn't run: {e}").into()),
    }
}
